// HasBundle applies the HasEdge predicate on the "bundle" edge.
func HasBundle() predicate.BundleAdConfigurations {
	return predicate.BundleAdConfigurations(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2O, true, BundleTable, BundleColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasBundleWith applies the HasEdge predicate on the "bundle" edge with a given conditions (other predicates).
func HasBundleWith(preds ...predicate.Bundles) predicate.BundleAdConfigurations {
	return predicate.BundleAdConfigurations(func(s *sql.Selector) {
		step := newBundleStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BundleAdConfigurations) predicate.BundleAdConfigurations {
	return predicate.BundleAdConfigurations(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BundleAdConfigurations) predicate.BundleAdConfigurations {
	return predicate.BundleAdConfigurations(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BundleAdConfigurations) predicate.BundleAdConfigurations {
	return predicate.BundleAdConfigurations(sql.NotPredicates(p))
}
